-- PostgreSQL para la demo en Render. Ejecutar mediante una importación explícita.
-- No elimina objetos ni datos. El importador ejecuta todo dentro de una transacción.
CREATE SCHEMA IF NOT EXISTS dbo;

CREATE TABLE IF NOT EXISTS dbo."Usuario" (
  "IdUsuario" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Nombres" varchar(80) NOT NULL,
  "Apellidos" varchar(80) NOT NULL,
  "Correo" varchar(150) NOT NULL,
  "ContrasenaHash" varchar(255) NOT NULL,
  "Estado" boolean NOT NULL DEFAULT true,
  "FechaRegistro" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "UQ_Usuario_Correo" UNIQUE ("Correo")
);
CREATE UNIQUE INDEX IF NOT EXISTS "UQ_Usuario_Correo_CI" ON dbo."Usuario" (lower("Correo"));

CREATE TABLE IF NOT EXISTS dbo."Docente" (
  "IdDocente" integer PRIMARY KEY,
  CONSTRAINT "FK_Docente_Usuario" FOREIGN KEY ("IdDocente") REFERENCES dbo."Usuario" ("IdUsuario")
);
CREATE TABLE IF NOT EXISTS dbo."Alumno" (
  "IdAlumno" integer PRIMARY KEY,
  CONSTRAINT "FK_Alumno_Usuario" FOREIGN KEY ("IdAlumno") REFERENCES dbo."Usuario" ("IdUsuario")
);
CREATE TABLE IF NOT EXISTS dbo."Curso" (
  "IdCurso" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Nombre" varchar(150) NOT NULL,
  "Codigo" varchar(30) NOT NULL,
  "IdDocente" integer NOT NULL,
  "Estado" boolean NOT NULL DEFAULT true,
  CONSTRAINT "UQ_Curso_Codigo" UNIQUE ("Codigo"),
  CONSTRAINT "FK_Curso_Docente" FOREIGN KEY ("IdDocente") REFERENCES dbo."Docente" ("IdDocente")
);
CREATE UNIQUE INDEX IF NOT EXISTS "UQ_Curso_Codigo_CI" ON dbo."Curso" (lower("Codigo"));

CREATE TABLE IF NOT EXISTS dbo."Matricula" (
  "IdMatricula" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "IdCurso" integer NOT NULL,
  "IdAlumno" integer NOT NULL,
  "FechaMatricula" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "Estado" varchar(10) NOT NULL DEFAULT 'ACTIVA',
  CONSTRAINT "FK_Matricula_Curso" FOREIGN KEY ("IdCurso") REFERENCES dbo."Curso" ("IdCurso"),
  CONSTRAINT "FK_Matricula_Alumno" FOREIGN KEY ("IdAlumno") REFERENCES dbo."Alumno" ("IdAlumno"),
  CONSTRAINT "UQ_Matricula_Curso_Alumno" UNIQUE ("IdCurso", "IdAlumno"),
  CONSTRAINT "CK_Matricula_Estado" CHECK ("Estado" IN ('ACTIVA', 'RETIRADA'))
);
CREATE TABLE IF NOT EXISTS dbo."Tarea" (
  "IdTarea" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "IdCurso" integer NOT NULL,
  "Titulo" varchar(200) NOT NULL,
  "Descripcion" text NOT NULL,
  "ArchivoReferencia" varchar(500),
  "FechaPublicacion" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "FechaLimite" timestamptz NOT NULL,
  "Estado" varchar(12) NOT NULL DEFAULT 'PUBLICADA',
  CONSTRAINT "FK_Tarea_Curso" FOREIGN KEY ("IdCurso") REFERENCES dbo."Curso" ("IdCurso"),
  CONSTRAINT "CK_Tarea_Estado" CHECK ("Estado" IN ('BORRADOR', 'PUBLICADA', 'CERRADA')),
  CONSTRAINT "CK_Tarea_Fechas" CHECK ("FechaLimite" > "FechaPublicacion")
);
CREATE TABLE IF NOT EXISTS dbo."Entrega" (
  "IdEntrega" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "IdTarea" integer NOT NULL,
  "IdAlumno" integer NOT NULL,
  "ArchivoUrl" varchar(500) NOT NULL,
  "Comentario" varchar(500),
  "FechaEntrega" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "Estado" varchar(10) NOT NULL DEFAULT 'ENTREGADA',
  "Nota" decimal(4,2),
  "ObservacionDocente" varchar(500),
  CONSTRAINT "FK_Entrega_Tarea" FOREIGN KEY ("IdTarea") REFERENCES dbo."Tarea" ("IdTarea"),
  CONSTRAINT "FK_Entrega_Alumno" FOREIGN KEY ("IdAlumno") REFERENCES dbo."Alumno" ("IdAlumno"),
  CONSTRAINT "UQ_Entrega_Tarea_Alumno" UNIQUE ("IdTarea", "IdAlumno"),
  CONSTRAINT "CK_Entrega_Estado" CHECK ("Estado" IN ('ENTREGADA', 'REVISADA')),
  CONSTRAINT "CK_Entrega_Nota" CHECK ("Nota" IS NULL OR ("Nota" >= 0 AND "Nota" <= 20))
);

-- PDF privados de la demo. Evita depender del disco efímero de Render Free.
CREATE TABLE IF NOT EXISTS dbo."Archivo" (
  "Nombre" varchar(80) PRIMARY KEY,
  "Contenido" bytea NOT NULL,
  CONSTRAINT "CK_Archivo_Tamano" CHECK (octet_length("Contenido") BETWEEN 1 AND 10485760)
);

CREATE INDEX IF NOT EXISTS "IX_Curso_IdDocente" ON dbo."Curso" ("IdDocente");
CREATE INDEX IF NOT EXISTS "IX_Matricula_IdAlumno" ON dbo."Matricula" ("IdAlumno");
CREATE INDEX IF NOT EXISTS "IX_Tarea_IdCurso" ON dbo."Tarea" ("IdCurso");
CREATE INDEX IF NOT EXISTS "IX_Entrega_IdTarea" ON dbo."Entrega" ("IdTarea");
CREATE INDEX IF NOT EXISTS "IX_Entrega_IdAlumno" ON dbo."Entrega" ("IdAlumno");
